const items = $input.all();

return items.map(item => {
  const bin = item.binary?.data; 

  const directory = bin?.directory || "";
  const fileName  = bin?.fileName  || "";

  return {
    json: {
      fileName,
      directory,
      // full path รวมชื่อไฟล์ด้วย
      path: directory
        ? `${directory}/${fileName}`
        : fileName
    },
    binary: item.binary   
  };
});

const items = $input.all();

// ดึงชื่อโฟลเดอร์สุดท้าย เช่น "ก", "ข", "สยามบียู"
const folder = items[0].json.directory.split('/').pop();

// normalize unicode ให้คงที่
const normalized = folder.normalize("NFC");

// hash สำหรับ schema
const schema = 's_' + Buffer.from(normalized).toString('hex').slice(0, 16);

// คืนค่าพร้อมข้อมูลเดิมทุก item + binary เดิม
return items.map(item => ({
  json: {
    ...item.json,
    schema,
  },
  binary: item.binary,
}));
